function routePersistenceIntegrityFailure(error) {
  return Boolean(error && ROUTE_PERSISTENCE_INTEGRITY_CODES.has(error.code))
}

function callbackFailureRequiresImmediateAbort(error) {
  const code = error && typeof error.code === 'string' ? error.code : ''
  return routePersistenceIntegrityFailure(error) ||
    [
      'CHECK_REPORT_INVALID',
      'ROLE_REPORT_INVALID',
      'CRASH_ADOPTION_CONFLICT',
      'CODEX_USAGE_INVALID',
      'USAGE_REGRESSION',
      'INVALID_USAGE_REPORT',
      'INCOMPLETE_USAGE_REPORT',
      'INCOMPLETE_USAGE_ACCOUNTING',
      'ACTIVATION_RECEIPT_INVALID',
      'BUDGET_EXHAUSTED',
    ].includes(code) ||
    /^(?:ACCOUNTING_|RECOVERY_CHECKPOINT_|RUN_RECORD_UNSAFE)/u.test(code) ||
    /(?:FOREIGN|TAMPER|HASH_MISMATCH|SIGNATURE_INVALID|ROLLBACK)/u.test(code) ||
    /^TRANSCRIPT_(?:CHAIN|CONTENT|GAP|HASH|OVERFLOW_AMBIGUOUS|PAYLOAD|READ_DRIFT|TRUNCATED|UNRECOGNIZED)/u.test(code)
}

function promotedMutationFailureRequiresRollback(error) {
  const code = error && typeof error.code === 'string' ? error.code : ''
  return callbackFailureRequiresImmediateAbort(error) ||
    [
      'CONCURRENT_MUTATION',
      'MANIFEST_INVALID',
      'MUTATION_AUTHORITY_INVALID',
      'MUTATION_ISOLATION_MISMATCH',
      'MUTATION_PERMIT_INVALID',
      'MUTATION_RESULT_MISMATCH',
      'PREIMAGE_UNSAFE',
      'WORKER_PROMOTION_INVALID',
      'WORKER_ROLLBACK_CONFLICT',
      'WORKER_ROLLBACK_FAILED',
      'WORKER_WORKSPACE_RECOVERY_FAILED',
    ].includes(code) ||
    /(?:FOREIGN|TAMPER|HASH_MISMATCH|SIGNATURE_INVALID|ROLLBACK)/u.test(code)
}

function deepFreezeJson(value) {
  if (!value || typeof value !== 'object' || Object.isFrozen(value)) return value
  for (const child of Object.values(value)) deepFreezeJson(child)
  return Object.freeze(value)
}

function immutableTerminalIntent(outcome, result) {
  let bytes
  try { bytes = stableStringify({ outcome, result }) } catch (error) {
    throw new SupervisorIntegrationError(
      'TERMINAL_INTENT_INVALID',
      'terminal intent must contain only bounded canonical JSON values',
      { cause: error.message },
    )
  }
  if (Buffer.byteLength(bytes, 'utf8') > TERMINAL_INTENT_MAX_BYTES) {
    throw new SupervisorIntegrationError(
      'TERMINAL_INTENT_INVALID',
      'terminal intent exceeds its finite canonical byte boundary',
      { maximumBytes: TERMINAL_INTENT_MAX_BYTES },
    )
  }
  return deepFreezeJson(JSON.parse(bytes))
}

function automaticWaitingRequiresUserAuthority(analysis, verifyAuthority) {
  // Route-analysis prose is untrusted advisory output. It cannot manufacture
  // authority by labeling its own uncertainty, side effect, or reversibility.
  // Suspension is available only through an injected controller verifier that
  // authenticates an explicit immutable user/target/cost/external decision.
  if (typeof verifyAuthority !== 'function') return false
  const receipt = verifyAuthority(analysis)
  return Boolean(receipt && receipt.authenticated === true &&
    ['EXPLICIT_USER_DECISION', 'EXTERNAL_WRITE_AUTHORITY', 'COST_AUTHORITY', 'TARGET_AUTHORITY']
      .includes(receipt.authorityClass) &&
    /^[a-f0-9]{64}$/u.test(receipt.evidenceHash || ''))
}

function initialProductFrontier(decision) {
  return Array.from(
    { length: Math.max(1, Number(decision && decision.usefulWorkerCount || 1)) },
    (_, index) => `work-${index + 1}`,
  )
}

function validateCodexAdvisoryPayloadBounds(value, limits = {}) {
  const maximumStringBytes = Number(limits.maximumStringBytes || 16 * 1024)
  const maximumAggregateBytes = Number(limits.maximumAggregateBytes || 64 * 1024)
  const maximumArrayItems = Number(limits.maximumArrayItems || 128)
  const maximumObjectKeys = Number(limits.maximumObjectKeys || 128)
  const maximumNodes = Number(limits.maximumNodes || 2048)
  const maximumDepth = Number(limits.maximumDepth || 16)
  const stack = [{ value, depth: 0 }]
  const seen = new Set()
  let aggregateBytes = 0
  let nodes = 0
  let strings = 0
  let maximumObservedStringBytes = 0
  const violations = []
  while (stack.length > 0 && violations.length < 8) {
    const current = stack.pop()
    nodes += 1
    if (nodes > maximumNodes) {
      violations.push('node-count')
      break
    }
    if (current.depth > maximumDepth) {
      violations.push('nesting-depth')
      continue
    }
    const item = current.value
    if (typeof item === 'string') {
      const bytes = Buffer.byteLength(item, 'utf8')
      strings += 1
      aggregateBytes += bytes
      maximumObservedStringBytes = Math.max(maximumObservedStringBytes, bytes)
      if (bytes > maximumStringBytes) violations.push('string-bytes')
      if (aggregateBytes > maximumAggregateBytes) violations.push('aggregate-string-bytes')
      continue
    }
    if (!item || typeof item !== 'object') continue
    if (seen.has(item)) {
      violations.push('cyclic-value')
      continue
    }
    seen.add(item)
    if (Array.isArray(item)) {
      if (item.length > maximumArrayItems) violations.push('array-items')
      for (let index = Math.min(item.length, maximumArrayItems) - 1; index >= 0; index -= 1) {
        stack.push({ value: item[index], depth: current.depth + 1 })
      }
      continue
    }
    const entries = Object.entries(item)
    if (entries.length > maximumObjectKeys) violations.push('object-keys')
    for (let index = Math.min(entries.length, maximumObjectKeys) - 1; index >= 0; index -= 1) {
      const [key, nested] = entries[index]
      const keyBytes = Buffer.byteLength(key, 'utf8')
      aggregateBytes += keyBytes
      maximumObservedStringBytes = Math.max(maximumObservedStringBytes, keyBytes)
      if (keyBytes > maximumStringBytes) violations.push('key-bytes')
      if (aggregateBytes > maximumAggregateBytes) violations.push('aggregate-string-bytes')
      stack.push({ value: nested, depth: current.depth + 1 })
    }
  }
  const summary = Object.freeze({
    nodes,
    strings,
    aggregateBytes,
    maximumObservedStringBytes,
    violations: Object.freeze([...new Set(violations)].sort()),
  })
  return Object.freeze({
    valid: summary.violations.length === 0,
    summary,
    evidenceHash: hashText(stableStringify(summary)),
  })
}

function codexPhysicalExecutionReceipt(decision, options = {}) {
  const validation = validateRouteDecision(decision)
  if (!validation.valid) {
    throw new SupervisorIntegrationError(
      'ROUTE_TOPOLOGY_INVALID',
      'Codex physical execution requires the exact validated route decision',
      { errors: validation.errors },
    )
  }
  const workerLaunches = Number(decision.usefulWorkerCount)
  const checkerLaunches = Number(
    decision.independentCheckingPlan && decision.independentCheckingPlan.checkerCount,
  )
  const gateLaunches = options.additionalGateLaunches === undefined
    ? 0 : Number(options.additionalGateLaunches)
  if (!Number.isSafeInteger(gateLaunches) || gateLaunches < 0 || gateLaunches > 1) {
    throw new SupervisorIntegrationError(
      'ROUTE_LAUNCH_REQUIREMENT_INVALID',
      'Codex physical execution permits zero or one exact pre-production model check',
    )
  }
  const analystLaunches = decision.routeSource === 'automatic' ? 1 : 0
  const basePhysicalLaunches = analystLaunches + workerLaunches + checkerLaunches
  // T1 + R1 + P1 + C is the economic launch target used to provision the
  // ordinary path: one transport contingency, one report correction, one
  // initial product repair, and its fresh checker seats. It is not a claim
  // that progress-authenticated repair succession has a numeric global cap.
  // Novel controller-bound failures may continue finitely until a stable
  // failure recurs, a candidate does not change, or acceptance passes.
  const boundedContingencyLaunches = 3 + checkerLaunches
  const body = Object.freeze({
    schemaVersion: 2,
    kind: 'codex-physical-execution',
    executionMode: decision.route === 'ROADMAP'
      ? DETERMINISTIC_ROADMAP_EXECUTION_MODE : 'direct-product-v1',
    route: decision.route,
    routeSource: decision.routeSource,
    routeDecisionHash: hashText(stableStringify(decision)),
    analystLaunches,
    workerLaunches,
    checkerLaunches,
    gateLaunches,
    basePhysicalLaunches,
    boundedContingencyLaunches,
    requiredChildLaunchesSemantics: 'economic-target',
    repairSuccession: Object.freeze({
      kind: 'progress-authenticated-finite-per-stable-failure',
      numericGlobalRepairCap: false,
      recurrenceAction: 'return-concrete-failure',
      unchangedCandidateAction: 'return-concrete-failure',
    }),
    requiredChildLaunches: basePhysicalLaunches + gateLaunches + boundedContingencyLaunches,
  })
  return Object.freeze({ ...body, receiptHash: hashText(stableStringify(body)) })
}

function checkerLaunchRuntimeFailure(request, decision, runId, error, binding = {}) {
  return Object.freeze({
    schemaVersion: '2.0.0',
    code: 'RUNTIME_FAILURE',
    description: 'A tool or execution environment failed before the requested check could finish.',
    stateClass: 'terminal',
    runId: typeof runId === 'string' && runId ? runId : 'autoprompt-controller',
    requestEnvelopeHash: binding.requestEnvelopeHash ||
      (decision && typeof decision.requestEnvelopeHash === 'string'
        ? decision.requestEnvelopeHash : null),
    currentVersionHash: request.candidateHash || null,
    candidateHash: request.candidateHash || null,
    completedResults: [],
    nextReadyWork: [],
    cause: {
      event: error && error.code || 'CHECKER_LAUNCH_FAILED',
      reason: 'The isolated checker transport failed; this result is non-authoritative and requires a fresh physical reassessment.',
      unblockPath: 'Launch one fresh evidence-bound checker reassessment.',
    },
    payloadSchemaId: 'autoprompt.checker-launch-reassessment.v2',
    payload: { error: serializeError(error) },
    recordedAt: new Date().toISOString(),
    contextId: binding.contextId || null,
  })
}

function workerTransportRuntimeFailure(request, decision, runId, error, binding = {}) {
  const failureHash = hashText(stableStringify({
    code: error && error.code || 'CHILD_TRANSPORT_TIMEOUT',
    workItemId: request.workItemId,
    candidateHash: request.candidateHash || null,
  }))
  return Object.freeze({
    schemaVersion: '2.0.0',
    reportType: 'result',
    outcome: 'FAILED',
    runId: typeof runId === 'string' && runId ? runId : 'autoprompt-controller',
    requestEnvelopeHash: binding.requestEnvelopeHash ||
      decision && decision.requestEnvelopeHash || null,
    assignmentId: request.workItemId,
    logicalRoleId: request.logicalRole || 'worker',
    physicalRoleId: binding.physicalRole || providerRoleForLogical(request.logicalRole || 'worker'),
    contextId: binding.contextId || `transport-timeout:${failureHash.slice(0, 24)}`,
    allAssignedItemsPass: false,
    successItems: [{
      id: 'provider-transport-completion',
      status: 'fail',
      evidenceIds: [failureHash],
    }],
    resourcesChanged: [],
    behaviorChanged: [],
    remainingConcerns: ['The provider transport ended before the assigned turn returned a canonical terminal result.'],
    filesChanged: [],
    commands: [],
    findingIds: [...new Set(
      Array.isArray(binding.findingIds) && binding.findingIds.length > 0
        ? binding.findingIds
        : [`provider-transport:${failureHash.slice(0, 24)}`],
    )],
    evidenceHashes: [failureHash],
    candidateHash: request.candidateHash || null,
    requestedTransition: Object.freeze({
      event: 'WORK_ITEM_VERIFIED',
      reason: 'Persist the provider transport failure as exact unsuccessful work evidence.',
      invalidateEvidenceIds: [],
    }),
    terminalEnvelope: Object.freeze({
      status: 'CHILD_TRANSPORT_TIMEOUT',
      reason: 'The bounded child transport stopped responding before it returned a typed result.',
      details: Object.freeze({
        workItemId: request.workItemId,
        logicalRole: request.logicalRole || 'worker',
        evidenceHash: failureHash,
      }),
    }),
  })
}

function canonicalCheckerReassessment(input, expected = {}) {
  if (!input || typeof input !== 'object' || Array.isArray(input)) {
    throw new SupervisorIntegrationError(
      'CHECK_RETRY_STATE_INVALID',
      'checker reassessment must be a bounded structured controller receipt',
    )
  }
  const allowedKeys = new Set([
    'code', 'priorResultEvidenceHash', 'conflictingCheckerId', 'reassignedCheckerId',
    'evidenceId', 'methodClass', 'methodHash', 'invalidFieldIds', 'checkIds',
  ])
  if (Object.keys(input).some(key => !allowedKeys.has(key)) ||
      !CHECKER_REASSESSMENT_CODES.has(input.code) ||
      !/^[a-f0-9]{64}$/u.test(input.priorResultEvidenceHash || '') ||
      (expected.resultHash && input.priorResultEvidenceHash !== expected.resultHash)) {
    throw new SupervisorIntegrationError(
      'CHECK_RETRY_STATE_INVALID',
      'checker reassessment code and exact prior result evidence must be canonical',
    )
  }
  const checkerId = value => typeof value === 'string' &&
    /^independent-check-\d+(?:-repair-\d+)?(?:-runtime-retry-\d+)?$/u.test(value)
  if (input.conflictingCheckerId !== undefined && input.conflictingCheckerId !== null &&
      !checkerId(input.conflictingCheckerId)) {
    throw new SupervisorIntegrationError('CHECK_RETRY_STATE_INVALID', 'conflicting checker identity is not canonical')
  }
  if (input.reassignedCheckerId !== undefined &&
      (!checkerId(input.reassignedCheckerId) ||
       (expected.checkerId && input.reassignedCheckerId !== expected.checkerId))) {
    throw new SupervisorIntegrationError('CHECK_RETRY_STATE_INVALID', 'reassigned checker identity is not canonical')
  }
  if (input.evidenceId !== undefined &&
      (typeof input.evidenceId !== 'string' || !input.evidenceId.trim() || input.evidenceId.length > 256)) {
    throw new SupervisorIntegrationError('CHECK_RETRY_STATE_INVALID', 'conflicting evidence identity is not bounded')
  }
  if (input.methodClass !== undefined && !INDEPENDENT_REFERENCE_METHOD_CLASSES.has(input.methodClass)) {
    throw new SupervisorIntegrationError('CHECK_RETRY_STATE_INVALID', 'conflicting reference-method class is not canonical')
  }
  if (input.methodHash !== undefined && !/^[a-f0-9]{64}$/u.test(input.methodHash)) {
    throw new SupervisorIntegrationError('CHECK_RETRY_STATE_INVALID', 'conflicting reference-method hash is not canonical')
  }
  for (const field of ['invalidFieldIds', 'checkIds']) {
    if (input[field] !== undefined && (!uniqueStrings(input[field]) || input[field].length > 64 ||
        input[field].some(value => typeof value !== 'string' || !value || value.length > 512))) {
      throw new SupervisorIntegrationError(
        'CHECK_RETRY_STATE_INVALID',
        `checker reassessment ${field} must be a bounded unique string list`,
      )
    }
  }
  const correctionShapes = {
    TEST_OUTCOMES_INVALID: {
      invalidFieldIds: ['payload.testOutcomes'], checkIds: 'NONEMPTY',
    },
    EVIDENCE_CONSUMPTION_INVALID: {
      invalidFieldIds: ['payload.evidenceIds'], checkIds: 'EMPTY',
    },
    REFERENCE_METHOD_INVALID: {
      invalidFieldIds: ['payload.referenceMethod'], checkIds: 'EMPTY',
    },
    CHECK_REPORT_INVALID: {
      invalidFieldIds: ['code', 'payload'], checkIds: 'NONEMPTY',
    },
    DUPLICATE_UNDERLYING_EVIDENCE: {
      invalidFieldIds: ['payload.evidenceIds'], checkIds: 'EMPTY',
    },
    DUPLICATE_REFERENCE_METHOD: {
      invalidFieldIds: ['payload.referenceMethod'], checkIds: 'EMPTY',
    },
    DUPLICATE_REFERENCE_METHOD_CLASS: {
      invalidFieldIds: ['payload.referenceMethod'], checkIds: 'EMPTY',
    },
  }
  const correctionShape = correctionShapes[input.code]
  const carriesCorrectionScope = input.invalidFieldIds !== undefined || input.checkIds !== undefined
  if (correctionShape && carriesCorrectionScope) {
    const exactFields = Array.isArray(input.invalidFieldIds) &&
      stableStringify(input.invalidFieldIds) ===
      stableStringify(correctionShape.invalidFieldIds)
    const exactChecks = Array.isArray(input.checkIds) &&
      (correctionShape.checkIds === 'NONEMPTY' ? input.checkIds.length > 0 : input.checkIds.length === 0)
    if (!exactFields || !exactChecks) {
      throw new SupervisorIntegrationError(
        'CHECK_RETRY_STATE_INVALID',
        `checker reassessment ${input.code} has a noncanonical correction scope`,
      )
    }
  } else if (!correctionShape && carriesCorrectionScope) {
    throw new SupervisorIntegrationError(
      'CHECK_RETRY_STATE_INVALID',
      `checker reassessment ${input.code} cannot carry report-correction fields`,
    )
  }
  return Object.freeze({
    code: input.code,
    priorResultEvidenceHash: input.priorResultEvidenceHash,
    ...(input.conflictingCheckerId !== undefined
      ? { conflictingCheckerId: input.conflictingCheckerId } : {}),
    ...(input.reassignedCheckerId !== undefined
      ? { reassignedCheckerId: input.reassignedCheckerId } : {}),
    ...(input.evidenceId !== undefined ? { evidenceId: input.evidenceId.trim() } : {}),
    ...(input.methodClass !== undefined ? { methodClass: input.methodClass } : {}),
    ...(input.methodHash !== undefined ? { methodHash: input.methodHash } : {}),
    ...(input.invalidFieldIds !== undefined ? { invalidFieldIds: [...input.invalidFieldIds] } : {}),
    ...(input.checkIds !== undefined ? { checkIds: [...input.checkIds] } : {}),
  })
}

function checkerVerdictPassed(logicalRole, result) {
  return CHECKER_ROLES.has(logicalRole) && Boolean(result) && result.code === 'PASS'
}

function containsStructuredFailureEvidence(value, seen = new Set(), depth = 0) {
  if (value === null || value === undefined || depth > 12) return false
  if (typeof value !== 'object') return false
  if (seen.has(value)) return false
  seen.add(value)
  if (Array.isArray(value)) {
    return value.some(item => containsStructuredFailureEvidence(item, seen, depth + 1))
  }
  for (const [key, nested] of Object.entries(value)) {
    const normalizedKey = key.toLowerCase().replace(/[_-]/gu, '')
    if (normalizedKey === 'exitcode' && Number.isFinite(Number(nested)) && Number(nested) !== 0) {
      return true
    }
    if (['passed', 'success', 'successful'].includes(normalizedKey) && nested === false) return true
    if (['code', 'status', 'outcome', 'verdict', 'event', 'state'].includes(normalizedKey) &&
        typeof nested === 'string' &&
        /^(?:FAIL|FAILED|ERROR|REJECTED|ASSERTION_FAILED|TEST_FAILED)$/u.test(nested.trim().toUpperCase())) {
      return true
    }
    if (/(?:finding|defect)ids?$/u.test(normalizedKey) &&
        ((Array.isArray(nested) && nested.length > 0) ||
          (typeof nested === 'string' && nested.trim()))) return true
    if (containsStructuredFailureEvidence(nested, seen, depth + 1)) return true
  }
  return false
}

function checkerResultHasExactVerificationLimitation(result) {
  if (!result || !['FAIL', 'CHECK_INCONCLUSIVE'].includes(result.code)) return false
  const payload = result.payload && typeof result.payload === 'object' ? result.payload : {}
  const limitation = payload.verificationLimitation &&
    typeof payload.verificationLimitation === 'object' &&
    !Array.isArray(payload.verificationLimitation)
    ? payload.verificationLimitation : null
  const limitationKeys = limitation ? Object.keys(limitation).sort() : []
  if (!limitation || stableStringify(limitationKeys) !== stableStringify([
    'capabilityId', 'explicitUserDeliverable', 'kind', 'observedVersionDefectIds',
  ]) || limitation.kind !== 'CAPABILITY_UNAVAILABLE' ||
      typeof limitation.capabilityId !== 'string' ||
      !/^[a-z0-9][a-z0-9._:-]{0,127}$/u.test(limitation.capabilityId) ||
      typeof limitation.explicitUserDeliverable !== 'boolean' ||
      !uniqueStrings(limitation.observedVersionDefectIds) ||
      limitation.observedVersionDefectIds.some(id => id.length > 256)) return false
  if (limitation.explicitUserDeliverable || limitation.observedVersionDefectIds.length > 0) return false
  // The empty observed-defect list must agree with the rest of the structured
  // report.  Otherwise a checker could accidentally (or adversarially) attach
  // a capability-limitation object to real failing evidence and turn a product
  // defect into DONE_WITH_VERIFICATION_LIMITATIONS at normalization time.
  const structuredFindingCollections = [
    result.findingIds,
    result.findings,
    payload.findingIds,
    payload.findings,
    payload.defectIds,
    payload.observedVersionDefectIds,
  ]
  if (structuredFindingCollections.some(value => Array.isArray(value) && value.length > 0)) {
    return false
  }
  if (explicitFindingIds(result, payload, result.cause).length > 0) return false
  if (Array.isArray(payload.testOutcomes) &&
      payload.testOutcomes.some(item => item && item.status === 'FAIL')) return false
  const payloadWithoutLimitation = { ...payload }
  delete payloadWithoutLimitation.verificationLimitation
  if (containsStructuredFailureEvidence([
    result.cause,
    result.completedResults,
    result.commands,
    payloadWithoutLimitation,
  ])) return false
  // The exact typed payload is the authority.  Free-form model vocabulary is
  // diagnostic only: an otherwise valid limitation must not become a task
  // failure because the checker called the same event by a novel name.
  return true
}

function canonicalizeCheckerVerificationLimitation(result) {
  if (!checkerResultHasExactVerificationLimitation(result)) return result
  const cause = result.cause && typeof result.cause === 'object' ? result.cause : {}
  const suppliedEvent = typeof cause.event === 'string' ? cause.event : ''
  const canonicalEvent = VERIFICATION_LIMITATION_CODES.has(suppliedEvent)
    ? suppliedEvent : DEFAULT_VERIFICATION_LIMITATION_EVENT
  return {
    ...result,
    code: 'CHECK_INCONCLUSIVE',
    description: 'A required check could not determine whether the exact result passes.',
    stateClass: 'intermediate',
    cause: {
      event: canonicalEvent,
      reason: typeof cause.reason === 'string' && cause.reason.length > 0
        ? cause.reason : 'the checker reported an unavailable external verification capability',
      unblockPath: typeof cause.unblockPath === 'string' && cause.unblockPath.length > 0
        ? cause.unblockPath : null,
    },
  }
}

function canonicalizeCheckerTerminalResult(result) {
  const canonical = canonicalizeCheckerVerificationLimitation(result)
  const outcomes = canonical && canonical.payload && canonical.payload.testOutcomes
  if (!canonical || canonical.code !== 'PASS' || !Array.isArray(outcomes) ||
      !outcomes.some(item => item && item.status === 'FAIL')) return canonical
  // A model-authored PASS and a model-authored failing observation disagree.
  // Neither spelling gets to manufacture product authority.  A concrete FAIL
  // must be the checker's aggregate verdict and must be bound to the controller
  // observation protocol; this contradiction instead consumes the one fresh
  // checker reassessment.
  return {
    ...canonical,
    code: 'CHECK_INCONCLUSIVE',
    description: 'A required check could not determine whether the exact result passes.',
    stateClass: 'intermediate',
    cause: {
      event: 'CHECKER_VERDICT_CONTRADICTION',
      reason: 'The checker aggregate PASS contradicts at least one named failing observation.',
      unblockPath: 'Run one fresh independent reassessment against the same frozen exact version and return one consistent aggregate verdict.',
    },
  }
}

function canonicalVerificationLimitationSummaries(value, options = {}) {
  if (!Array.isArray(value) || value.length === 0 || value.length > 3) return null
  const seen = new Set()
  const canonical = []
  for (const item of value) {
    const keys = item && typeof item === 'object' && !Array.isArray(item)
      ? Object.keys(item).sort() : []
    if (stableStringify(keys) !== stableStringify([
      'checkerId', 'resultHash', 'verificationLimitation',
    ]) || typeof item.checkerId !== 'string' || !item.checkerId || item.checkerId.length > 160 ||
        !/^[a-f0-9]{64}$/u.test(item.resultHash || '') || seen.has(item.checkerId) ||
        !checkerResultHasExactVerificationLimitation({
          code: 'CHECK_INCONCLUSIVE',
          payload: { verificationLimitation: item.verificationLimitation },
        })) return null
    seen.add(item.checkerId)
    canonical.push(Object.freeze({
      checkerId: item.checkerId,
      resultHash: item.resultHash,
      verificationLimitation: Object.freeze({ ...item.verificationLimitation }),
    }))
  }
  const sorted = canonical.sort((left, right) => left.checkerId.localeCompare(right.checkerId))
  if (options.requireCanonicalOrder === true && stableStringify(value) !== stableStringify(sorted)) return null
  return Object.freeze(sorted)
}

function unsuccessfulWorkTerminal(workItemId, result, options = {}) {
  const code = typeof options.code === 'string' && /^[A-Z][A-Z0-9_]+$/u.test(options.code)
    ? options.code : 'IMPLEMENTATION_WORK_UNSUCCESSFUL'
  const reason = typeof options.reason === 'string' && options.reason.length > 0
    ? options.reason
    : 'the implementation worker explicitly reported that its assigned implementation and author-side checks did not pass'
  const failedSuccessItemIds = Array.isArray(result && result.successItems)
    ? result.successItems
        .filter(item => !item || item.status !== 'pass')
        .map(item => item && (item.id || item.successItemId))
        .filter(value => typeof value === 'string' && value.length > 0)
        .slice(0, 32)
    : []
  return Object.freeze({
    outcome: 'FAILED',
    terminalEnvelope: Object.freeze({
      code,
      status: code,
      reason,
      workItemId,
      workResultHash: hashText(stableStringify(result)),
      failedSuccessItemIds: Object.freeze(failedSuccessItemIds),
    }),
  })
}

function canonicalRejectedCheckerReceipts(value, options = {}) {
  const allowEmpty = options.allowEmpty !== false
  const receipts = value === undefined || value === null ? [] : value
  if (!Array.isArray(receipts) || (!allowEmpty && receipts.length === 0)) {
    throw new SupervisorIntegrationError(
      'REPAIR_RECOVERY_INVALID',
      `cumulative checker receipt evidence must contain ${allowEmpty ? 'zero or more' : 'one or more'} bounded pointers`,
    )
  }
  const expectedKeys = ['bytes', 'hash', 'name', 'path', 'resultHash']
  const seen = new Set()
  const canonical = receipts.map(receipt => {
    const keys = receipt && typeof receipt === 'object' && !Array.isArray(receipt)
      ? Object.keys(receipt).sort() : []
    if (stableStringify(keys) !== stableStringify(expectedKeys) ||
        !/^independent-check-\d+(?:-repair-\d+)?(?:-runtime-retry-1|-scratch-confirmation-1)?$/u
          .test(receipt && receipt.name || '') ||
        typeof receipt.path !== 'string' || !path.isAbsolute(receipt.path) || receipt.path.length > 4096 ||
        !/^[a-f0-9]{64}$/u.test(receipt.hash || '') ||
        !/^[a-f0-9]{64}$/u.test(receipt.resultHash || '') ||
        !Number.isSafeInteger(receipt.bytes) || receipt.bytes < 1) {
      throw new SupervisorIntegrationError(
        'REPAIR_RECOVERY_INVALID',
        'cumulative checker receipt evidence contains a malformed or unbounded pointer',
      )
    }
    const identity = stableStringify([receipt.name, receipt.hash, receipt.resultHash])
    if (seen.has(identity)) {
      throw new SupervisorIntegrationError(
        'REPAIR_RECOVERY_INVALID',
        'cumulative checker receipt evidence contains a duplicate pointer',
      )
    }
    seen.add(identity)
    return Object.freeze({
      name: receipt.name, path: receipt.path, hash: receipt.hash,
      bytes: receipt.bytes, resultHash: receipt.resultHash,
    })
  })
  return Object.freeze(canonical)
}

function appendRejectedCheckerReceipt(receipts, pointer, resultHash) {
  const prior = canonicalRejectedCheckerReceipts(receipts)
  const next = {
    name: pointer && pointer.name,
    path: pointer && pointer.path,
    hash: pointer && pointer.hash,
    bytes: pointer && pointer.bytes,
    resultHash,
  }
  const identity = stableStringify([next.name, next.hash, next.resultHash])
  const appended = prior.filter(item =>
    stableStringify([item.name, item.hash, item.resultHash]) !== identity)
  appended.push(next)
  return canonicalRejectedCheckerReceipts(appended, { allowEmpty: false })
}

function canonicalRepairFailureFingerprintChain(value) {
  const chain = value === undefined || value === null ? [] : value
  if (!Array.isArray(chain) || chain.some(item => !/^[a-f0-9]{64}$/u.test(item || '')) ||
      new Set(chain).size !== chain.length) {
    throw new SupervisorIntegrationError(
      'REPAIR_RECOVERY_INVALID',
      'repair recurrence state must be an ordered unique chain of semantic failure fingerprints',
    )
  }
  return Object.freeze([...chain])
}

function canonicalIndependentCheckerSeat(workItemId) {
  const match = /^independent-check-(\d+)(?:-repair-\d+)?(?:-runtime-retry-\d+|-scratch-confirmation-\d+)?$/u
    .exec(String(workItemId || ''))
  return match && Number(match[1]) >= 1 ? `independent-check-${Number(match[1])}` : null
}

function checkerReportCorrectionBinding(candidateHash, checkerId) {
  const checkerSeat = canonicalIndependentCheckerSeat(checkerId)
  if (!/^[a-f0-9]{64}$/u.test(candidateHash || '') || !checkerSeat) return null
  return Object.freeze({ candidateHash, checkerSeat })
}

function canonicalCheckerReportCorrectionBindings(value) {
  const bindings = value === undefined || value === null ? [] : value
  if (!Array.isArray(bindings)) {
    throw new SupervisorIntegrationError(
      'CHECK_RETRY_STATE_INVALID',
      'checker report-correction state must be an array of exact-version/seat bindings',
    )
  }
  const seen = new Set()
  const canonical = bindings.map(binding => {
    const keys = binding && typeof binding === 'object' && !Array.isArray(binding)
      ? Object.keys(binding).sort() : []
    const normalized = checkerReportCorrectionBinding(
      binding && binding.candidateHash,
      binding && binding.checkerSeat,
    )
    if (stableStringify(keys) !== stableStringify(['candidateHash', 'checkerSeat']) ||
        !normalized || normalized.checkerSeat !== binding.checkerSeat) {
      throw new SupervisorIntegrationError(
        'CHECK_RETRY_STATE_INVALID',
        'checker report-correction state contains a malformed exact-version/seat binding',
      )
    }
    const identity = `${normalized.candidateHash}\0${normalized.checkerSeat}`
    if (seen.has(identity)) {
      throw new SupervisorIntegrationError(
        'CHECK_RETRY_STATE_INVALID',
        'checker report-correction state repeats an exact-version/seat binding',
      )
    }
    seen.add(identity)
    return normalized
  })
  return Object.freeze(canonical.sort((left, right) =>
    left.candidateHash.localeCompare(right.candidateHash) ||
    left.checkerSeat.localeCompare(right.checkerSeat)))
}

function checkerImplementationFailureObservationFingerprint(result, assignedChecks = []) {
  if (!result || result.code !== 'FAIL') return null
  const reportedOutcomes = result.payload && result.payload.testOutcomes
  const effectiveAssignedChecks = assignedChecks.length > 0
    ? assignedChecks
    : Array.isArray(reportedOutcomes) && reportedOutcomes.every(item =>
        item && typeof item.command === 'string')
      ? [...new Set(reportedOutcomes.map(item => item.command))]
      : []
  const canonicalOutcomes = canonicalCheckerTestOutcomes(
    reportedOutcomes,
    effectiveAssignedChecks,
  )
  const failedOutcomes = canonicalOutcomes
    ? canonicalOutcomes.filter(item => item.status === 'FAIL') : []
  // observationId authenticates that these values were added by the controller
  // for one exact candidate. The controller-owned failureIdentity is derived
  // from the normalized harness command and assigned check ID. Raw output and
  // parsed case names are evidence only: the candidate can own test/config
  // files reached by an exact command, so renames, timestamps, temporary paths,
  // seeds, and other diagnostics must not manufacture semantic progress.
  const controllerBoundFailures = failedOutcomes.length > 0 && failedOutcomes.every(item =>
    /^[a-f0-9]{64}$/u.test(item.observationId || '') &&
    /^[a-f0-9]{64}$/u.test(item.commandHash || '') &&
    /^[a-f0-9]{64}$/u.test(item.fingerprint || '') &&
    /^[a-f0-9]{64}$/u.test(item.failureIdentity || ''))
    ? failedOutcomes.map(item => Object.freeze({
        failureIdentity: item.failureIdentity,
      }))
    : null
  // Compatibility/direct-embedding FAILs may predate controller observation
  // enrichment. Bind those conservatively to the complete assigned check IDs;
  // changing prose, findings, or unrelated candidate bytes cannot mint progress.
  const semanticFailures = controllerBoundFailures || [...new Set(effectiveAssignedChecks)]
    .sort().map(command => Object.freeze({ command }))
  return hashText(stableStringify({
    schemaVersion: 1,
    kind: controllerBoundFailures
      ? 'controller-bound-failed-observations' : 'assigned-check-failure-fallback',
    failures: semanticFailures.length > 0
      ? semanticFailures : [Object.freeze({ command: 'unassigned-check-matrix' })],
  }))
}

function checkerImplementationFailureHasControllerObservation(result) {
  const outcomes = result && result.payload && result.payload.testOutcomes
  return Boolean(result && result.code === 'FAIL' && Array.isArray(outcomes) &&
    outcomes.some(item => item && item.status === 'FAIL') &&
    outcomes.filter(item => item && item.status === 'FAIL').every(item =>
      typeof item.command === 'string' && item.command.length > 0 &&
      /^[a-f0-9]{64}$/u.test(item.observationId || '') &&
      /^[a-f0-9]{64}$/u.test(item.commandHash || '') &&
      /^[a-f0-9]{64}$/u.test(item.fingerprint || '') &&
      /^[a-f0-9]{64}$/u.test(item.failureIdentity || '')))
}

function aggregateRepairFailureFingerprint(failures) {
  const fingerprints = [...new Set((failures || [])
    .map(failure => failure && failure.failureObservationFingerprint)
    .filter(value => /^[a-f0-9]{64}$/u.test(value || '')))].sort()
  if (fingerprints.length === 0) return null
  return hashText(stableStringify({
    schemaVersion: 1,
    kind: 'aggregate-repair-failure-observations',
    fingerprints,
  }))
}

function roadmapPlanOracleForWorkItem(workItemId) {
  return /^roadmap-plan-recheck(?:-runtime-retry)?$/u.test(String(workItemId || ''))
    ? 'roadmap-plan-oracle-recheck'
    : 'roadmap-plan-oracle'
}

function checkerRecoveryNextReady(workItemId, result, disposition = null) {
  const id = String(workItemId || '')
  const code = result && result.code
  if ((/^independent-check-\d+/u.test(id) || /^roadmap-plan-(?:check|recheck)$/u.test(id)) &&
      checkerResultIsStructurallyUnboundPass(result)) {
    return disposition && disposition.stableLimitationNextReadyId
      ? [disposition.stableLimitationNextReadyId] : []
  }
  if ((/^independent-check-\d+/u.test(id) || /^roadmap-plan-(?:check|recheck)$/u.test(id)) && disposition) {
    if (checkerResultRequiresScratchConfirmation(result)) {
      return disposition.stableLimitationNextReadyId
        ? [disposition.stableLimitationNextReadyId] : []
    }
    if (stableCapabilityUnavailable(result)) {
      return disposition.stableLimitationNextReadyId
        ? [disposition.stableLimitationNextReadyId] : []
    }
    if (code === 'FAIL') return disposition.failureRepairId ? [disposition.failureRepairId] : []
    if (code !== 'PASS') {
      if (disposition.nonAuthoritativeRetryId) return [disposition.nonAuthoritativeRetryId]
      return disposition.stableLimitationNextReadyId
        ? [disposition.stableLimitationNextReadyId] : []
    }
  }
  if (['CHECK_INCONCLUSIVE', 'RUNTIME_FAILURE'].includes(code)) {
    if (/^roadmap-plan-(?:check|recheck)$/u.test(id)) return [`${id}-runtime-retry`]
    if (/^independent-check-\d+(?:-repair-\d+)?$/u.test(id)) return [`${id}-runtime-retry-1`]
  }
  if (code === 'FAIL') {
    if (id === 'roadmap-plan-check' || id === 'roadmap-plan-check-runtime-retry') {
      return ['roadmap-author-plan-repair']
    }
    if (/^independent-check-\d+$/u.test(id)) return ['work-1-repair-1']
  }
  return []
}

function stableCapabilityUnavailable(result) {
  return checkerResultHasExactVerificationLimitation(result)
}

function checkerResultIsStructurallyUnboundPass(result) {
  const disposition = result && result.payload &&
    result.payload.verificationObservationDisposition
  return Boolean(
    result && result.code === 'CHECK_INCONCLUSIVE' &&
    result.cause && [
      'CHECK_OBSERVATION_INCOMPLETE',
      'CHECK_OBSERVATION_CONTRADICTION',
    ].includes(result.cause.event) &&
    disposition && disposition.reportedAggregateCode === 'PASS'
  )
}

function durableNextReadyAfter(
  logicalRole,
  result,
  nextReady,
  fallback = [],
  workItemId = null,
  checkerRecoveryDisposition = null,
) {
  if (CHECKER_ROLES.has(logicalRole) && !checkerVerdictPassed(logicalRole, result)) {
    return checkerRecoveryNextReady(workItemId, result, checkerRecoveryDisposition)
  }
  return nextReady || fallback || []
}

function recoveryGroupNextReady(request = {}, completedWorkIds = []) {
  if (!Array.isArray(request.recoveryGroupWorkIds)) return request.nextReadyAfter || []
  const recoveryJoinWorkIds = request.recoveryJoinWorkIds === undefined
    ? request.recoveryJoinWorkId ? [request.recoveryJoinWorkId] : []
    : request.recoveryJoinWorkIds
  if (!uniqueStrings(request.recoveryGroupWorkIds) ||
      !uniqueStrings(recoveryJoinWorkIds) ||
      typeof request.workItemId !== 'string' || !request.workItemId) {
    throw new SupervisorIntegrationError(
      'CHECK_RETRY_STATE_INVALID',
      `recovery group continuation for ${request.workItemId || 'unknown'} is not an exact canonical work list`,
    )
  }
  const completed = new Set(completedWorkIds)
  completed.add(request.workItemId)
  const missing = request.recoveryGroupWorkIds.filter(workItemId => !completed.has(workItemId))
  return missing.length > 0 ? missing : recoveryJoinWorkIds
}

function authoritativeRequestNextReady(logicalRole, result, request = {}, completedWorkIds = [], fallback = []) {
  if (!CHECKER_ROLES.has(logicalRole) &&
      result && result.terminalEnvelope &&
      result.terminalEnvelope.status === 'CHILD_TRANSPORT_TIMEOUT') {
    return request.transportFailureRetryId ? [request.transportFailureRetryId] : []
  }
  return durableNextReadyAfter(
    logicalRole,
    result,
    recoveryGroupNextReady(request, completedWorkIds),
    fallback,
    request.workItemId || null,
    request.checkerRecoveryDisposition || null,
  )
}

function checkerDispositionSettlesNonAuthoritative(request = {}, result = null) {
  const disposition = request.checkerRecoveryDisposition
  return Boolean(
    checkerResultIsStructurallyUnboundPass(result) ||
    checkerResultRequiresScratchConfirmation(result) ||
    disposition &&
    disposition.nonAuthoritativeRetryId === null &&
    result && !['PASS', 'FAIL'].includes(result.code),
  )
}

function adoptedLeaseMatchesStage(route, logicalRole, stage) {
  const checker = CHECKER_ROLES.has(logicalRole)
  const roadmapWorkStageChecker = route === 'ROADMAP' && logicalRole === 'plan-checker'
  if (stage === 'work') return !checker || roadmapWorkStageChecker
  if (stage === 'check') return checker && !roadmapWorkStageChecker
  return stage === 'route' ? logicalRole === 'route-analyst' : false
}

function currentProductRecoveryWorkIds(decision, resumeState) {
  const workerCount = Math.max(1, Number(decision && decision.usefulWorkerCount || 1))
  const completed = new Set()
  for (const workItemId of resumeState && resumeState.completedWorkIds || []) {
    const match = /^(work-\d+)(?:-|$)/u.exec(String(workItemId || ''))
    if (match) completed.add(match[1])
  }
  return Array.from({ length: workerCount }, (_, index) => `work-${index + 1}`)
    .filter(workItemId => !completed.has(workItemId))
}

function terminalFinalizationDiagnostics(result = {}) {
  const terminalEnvelope = result.terminalEnvelope || null
  const terminalCause = terminalEnvelope && terminalEnvelope.cause || null
  return Object.freeze({
    terminalEnvelope,
    reason: result.reason || terminalEnvelope && terminalEnvelope.reason ||
      terminalCause && terminalCause.reason || 'typed runtime outcome',
    unblockPath: result.unblockPath || terminalEnvelope && terminalEnvelope.unblockPath ||
      terminalCause && terminalCause.unblockPath ||
      terminalEnvelope && terminalEnvelope.payload && terminalEnvelope.payload.unblockPath || null,
  })
}

function resolveTerminalReceiptCandidateHash({
  logicalRole,
  runtimeStateProvider,
  requestCandidateHash,
  resultCandidateHash,
}) {
  if (!CHECKER_ROLES.has(logicalRole)) return resultCandidateHash || null
  // The runtime provider is authoritative even when its canonical candidate is
  // deliberately null during pre-mutation ROADMAP checking. Fall back to the
  // inspected artifact only when no runtime provider exists at all.
  if (typeof runtimeStateProvider === 'function') {
    return runtimeStateProvider().candidateHash || null
  }
  return requestCandidateHash || null
}
const TARGET_MUTATOR_ROLES = new Set(['worker', 'roadmap-author'])
